examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchAiHandoff(
    from = MonarchAiAgentRef(name = {{from.name}}, id = {{from.id}}),
    to = MonarchAiHandoffTarget.Agent(MonarchAiAgentRef(name = {{to.name}}, id = {{to.id}})),
    reason = {{reason}},
    dateMillis = {{at|millis}},
    nowMillis = {{now|millis}},
)

